(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pair=x=>`<div class="bilingual"><div class="zh">${E(x?.[0]||'')}</div><div class="en">${E(x?.[1]||'')}</div></div>`;
const link=(u,l)=>/^https?:\/\//.test(u||'')?`<a href="${E(u)}" target="_blank" rel="noopener noreferrer">${E(l)}</a>`:'';
let snapshots={},care={},gaps={},active;
const themes=[['vaccine','疫苗与免疫预防','Vaccines & prevention',/vaccin|immuniz|immunis|prophylax|nirsevimab|clesrovimab/i],['therapy','治疗与临床结局','Therapy & outcomes',/treat|therap|antiviral|randomi[sz]|clinical trial|drug/i],['diagnostics','诊断与检测','Diagnostics',/diagnos|detect|screen|assay/i],['publichealth','流行病学与防控','Epidemiology & control',/epidemi|surveill|outbreak|burden|coverage|prevalence|incidence|transmission/i],['longterm','长期结局与特殊人群','Long-term outcomes',/long.term|long covid|sequela|pregnan|congenital|immunocomprom|persistent|cancer/i]];
function refs(s){return `<details><summary>解读依据 / Sources (${s?.length||0})</summary>${(s||[]).map(x=>`<p>${link(x.url,x.title)}</p>`).join('')}</details>`}
function careHtml(id){const c=care.profiles?.[id];if(!c)return `<section class="clinical-care"><h3>疫苗与抗病毒治疗 / Vaccines & antiviral care</h3><p>本物种尚未完成逐种临床核验，不能由同科病毒推断疫苗、药物或适应证。非人类病毒的管理也不等于人用抗病毒治疗。</p><p class="en">Species-specific clinical verification is unavailable. Family membership does not establish vaccine or drug applicability.</p></section>`;return `<section class="clinical-care"><h3>疫苗与抗病毒治疗 / Vaccines & antiviral care</h3><p class="observatory-caption">核对 / Reviewed ${E(care.checked)}</p><div class="care-grid">${[['vaccine','疫苗与免疫预防','Vaccines & immunoprevention'],['antiviral','抗病毒与支持治疗','Antivirals & supportive care']].map(([k,zh,en])=>`<article class="care-card"><h4>${zh}<small>${en}</small></h4>${[['status','现状 / Status'],['options','现有方式 / Approaches'],['limits','适用范围与限制 / Scope & limits']].map(([f,l])=>`<div><b>${l}</b>${pair(c[k]?.[f])}</div>`).join('')}</article>`).join('')}</div><p class="observatory-caption">获批、推荐使用、研究中是不同状态；地区、年龄与适应证以链接的监管和临床来源为准。论文更新不会自动改变医疗结论。<span class="en">Approval, recommendation and investigational use differ. Literature refresh does not automatically revise clinical statements.</span></p>${refs(c.sources)}</section>`}
function gapsHtml(id){const g=gaps.profiles?.[id];if(!g)return `<section class="gap-analysis"><h3>研究重点、难点与未来方向 / Research interpretation</h3><p>本物种尚无人工核验的综述。标题主题仅供阅读导航；资料少不能直接解释为研究空白，也不能据此推断疫苗或治疗前景。</p><p class="en">No curated synthesis is available. Sparse matches are not proof of a research gap or clinical prospects.</p></section>`;return `<section class="gap-analysis"><h3>研究重点、难点与瓶颈 / Priorities & barriers</h3><p class="observatory-caption">人工整理 / Curated interpretation · ${E(gaps.checked)}</p><div class="gap-grid">${[['focus','当前研究重点','Research priorities'],['difficulty','研究难点','Methodological difficulties'],['bottleneck','转化与实施瓶颈','Translation barriers'],['outlook','未来方向：条件性推断','Future directions: conditional inference']].map(([k,zh,en])=>`<article class="gap-card ${k==='outlook'?'outlook':''}"><h4>${zh}<small>${en}</small></h4>${pair(g[k])}</article>`).join('')}</div><div class="inference-basis"><b>推断依据与边界 / Basis & limits</b>${pair(g.basis)}</div>${refs(g.sources)}</section>`}
function mount(node,c){cancel();if(!node)return;const controller=new AbortController(),ctx={controller,timer:null,busy:false};active=ctx;let data=snapshots.profiles?.[c.id],theme='all',year='all',page=1,newIds=new Set();
node.className='detail-section observatory';node.innerHTML=`<div class="observatory-header"><div><div class="eyebrow">FIVE-YEAR RESEARCH OBSERVATORY</div><h2>近五年研究进展</h2><p class="en">A rolling five-year research view</p></div><button class="secondary" data-progress-refresh>更新五年资料 / Refresh</button></div><div class="observatory-nav"><button data-section=".progress-evidence">研究轨迹 / Evidence</button><button data-section=".gap-analysis">重点与瓶颈 / Gaps</button><button data-section=".clinical-care">疫苗与治疗 / Care</button></div><p class="observatory-caption">打开时读取已保存的五年样本；页面可见时每15分钟检查发布版本。样本、研究解读及医疗资料各有核对日期，不会仅凭新标题自动改写。</p><p class="en">Reads saved five-year samples on opening and checks every 15 minutes while visible. Samples, interpretation and clinical facts have separate review dates.</p><div class="observatory-status" role="status"></div><div class="progress-evidence"></div>${gapsHtml(c.id)}${careHtml(c.id)}`;
node.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>node.querySelector(b.dataset.section).scrollIntoView({behavior:'smooth',block:'start'}));
function render(){const root=node.querySelector('.progress-evidence');if(!data){root.innerHTML='<p>正在查询，尚无本地快照。 / Querying; no local snapshot.</p>';return}const items=data.items||[],bins=data.bins||[],counts=themes.map(t=>({t,n:items.filter(x=>t[3].test(x.title)).length}));const ranked=[...counts].sort((a,b)=>b.n-a.n);let filtered=items.filter(x=>(theme==='all'||themes.find(t=>t[0]===theme)?.[3].test(x.title))&&(year==='all'||(x.date>=bins[+year].from&&x.date<=bins[+year].to)));const max=Math.max(1,...bins.map(x=>x.total||0)),pages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,pages);
root.innerHTML=`<div class="progress-window"><b>${E(data.window?.from)} — ${E(data.window?.to)}</b><span>${items.length} 篇样本 / sampled papers</span></div><p class="observatory-caption">每年度区间最多12篇近期、名称匹配论文。柱形为筛选前的索引命中量，不是研究质量或突破数量；主题数仅指本样本，一篇可属于多个主题。</p><p class="en">Up to 12 recent title-matched papers per interval. Bars are raw index hits, not quality or breakthroughs. Theme counts overlap and describe this sample only.</p><div class="progress-timeline">${bins.map((b,i)=>`<button class="year-column ${year===String(i)?'selected':''}" data-year="${i}"><span>${b.total===null?'不可用':Number(b.total).toLocaleString()}</span><span class="year-bar" style="height:${Math.max(5,80*(b.total||0)/max)}px"></span><b>${E(b.from.slice(2,4))}–${E(b.to.slice(2,4))}</b><small>${E(b.from.slice(5,7))}月起</small></button>`).join('')}</div><div class="topic-summary"><b>样本阅读摘要 / Sample reading guide</b><p>${items.length?'这批标题中较常出现：'+ranked.filter(x=>x.n).slice(0,3).map(x=>E(x.t[1])+'（'+x.n+'）').join('、')+'。这不是疗效、趋势增长或研究共识的判断。':'本次查询没有可归类记录，请查看范围和连接状态。'}</p><p class="en">Frequent themes guide reading; they do not establish efficacy, growth trends or consensus.</p></div><div class="theme-buttons"><button data-theme="all" class="${theme==='all'?'selected':''}">全部 / All (${items.length})</button>${counts.map(({t,n})=>`<button data-theme="${t[0]}" class="${theme===t[0]?'selected':''}">${t[1]}<small>${t[2]} · ${n}</small></button>`).join('')}</div><div class="progress-filter-line"><span>${filtered.length} 篇匹配 / matches · ${year==='all'?'全部年份':E(bins[+year].from)+' – '+E(bins[+year].to)}</span><button data-clear-year>全部年份 / All years</button></div><div class="progress-papers">${filtered.slice((page-1)*8,page*8).map(x=>`<article class="progress-paper">${newIds.has(x.pmid)?'<span class="new-paper">新增 / New</span>':''}<time>${E(x.date)}</time><h4>${link(x.url,x.title)}</h4><p>${E(x.journal)} · ${E((x.publicationTypes||[]).filter(x=>x!=='IM').join(' · '))}</p><small>${x.doi?'DOI: '+E(x.doi)+' · ':''}PMID: ${E(x.pmid)}</small>${AtlasExtras.brief(x)}</article>`).join('')||'<p>本样本暂无匹配 / No matching papers in sample.</p>'}</div><div class="progress-pagination"><button data-pg="-1" ${page===1?'disabled':''}>上一页 / Previous</button><span>${page} / ${pages}</span><button data-pg="1" ${page===pages?'disabled':''}>下一页 / Next</button></div><details><summary>检索方法与年度检索式 / Methods & queries</summary><p>Europe PMC / PubMed；按首次发表日期分段，每段返回最多40条后做标题名称筛选，保留最多12条。不是穷尽综述，不包括预印本。</p>${bins.map(b=>`<p><b>${E(b.from)} — ${E(b.to)}</b> · ${E(b.status)}<br>${link('https://europepmc.org/search?query='+encodeURIComponent(b.query),'查看该区间完整检索 / Full query')}</p>`).join('')}</details>`;
root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{theme=b.dataset.theme;page=1;render()});root.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{year=b.dataset.year;page=1;render()});root.querySelector('[data-clear-year]').onclick=()=>{year='all';page=1;render()};root.querySelectorAll('[data-pg]').forEach(b=>b.onclick=()=>{page+=Number(b.dataset.pg);render()});}
async function refresh(){if(ctx.busy||active!==ctx)return;const s=node.querySelector('.observatory-status');if(location.protocol==='file:'){s.textContent='离线快照 / Offline snapshot · '+(data?.checked||'无数据');return}ctx.busy=true;node.querySelector('[data-progress-refresh]').disabled=true;s.textContent='正在检索五个年度区间… / Checking five intervals…';try{const res=await fetch('/api/progress?id='+encodeURIComponent(c.id),{cache:'no-store',signal:AbortSignal.any([controller.signal,AbortSignal.timeout(32000)])});if(!res.ok)throw Error();const next=await res.json();if(!Array.isArray(next.items)||next.bins?.length!==5)throw Error();if(active!==ctx)return;if(next.status==='partial'&&data){next.bins=next.bins.map(b=>{const old=data.bins?.find(x=>x.from===b.from&&x.to===b.to);return b.status==='error'&&old?{...old,status:'retained-snapshot'}:b});next.items=[...new Map(next.bins.flatMap(b=>b.items||[]).map(x=>[x.pmid,x])).values()].sort((a,b)=>b.date.localeCompare(a.date));}const old=new Set(data?.items?.map(x=>x.pmid)||[]);newIds=new Set(data?next.items.filter(x=>!old.has(x.pmid)).map(x=>x.pmid):[]);data=next;render();s.textContent=(next.status==='partial'?'部分区间未更新 / Partial':'五年资料已更新 / Updated')+' · '+next.checked.replace('T',' ').slice(0,19)+' UTC · '+newIds.size+' 篇新增至样本';}catch{if(active===ctx)s.textContent='更新未完成，保留快照；连接失败不代表没有研究。 / Update unavailable; retained snapshot. '+(data?.checked||'');}finally{if(active===ctx){ctx.busy=false;node.querySelector('[data-progress-refresh]').disabled=false;}}}
node.querySelector('[data-progress-refresh]').onclick=refresh;render();refresh();ctx.timer=setInterval(()=>{if(document.visibilityState==='visible')refresh()},900000);}
function cancel(){if(active){clearInterval(active.timer);active.controller.abort();active=null}}
window.ResearchObservatory={init(p,c,g){snapshots=p||{};care=c||{};gaps=g||{}},mount,cancel};
})();
